import {navigationPage} from './navigation.js';
import './i18n.js';
import {addUpdates} from './updates-ui.js';
import {getSettings,saveSettings,avatarSVG,escapeHTML as esc} from './settings.js';
const option=(value,label,current)=>`<option value="${value}" ${value===current?'selected':''}>${label}</option>`;
const select=(key,label,items,s)=>`<label>${label}<select data-setting="${key}">${items.map(([v,l])=>option(v,l,s[key])).join('')}</select></label>`;
const dialog=document.createElement('dialog');dialog.id='preferences';document.body.append(dialog);
export function renderSettings(){const s=getSettings();dialog.innerHTML=`<button class="dialog-close" aria-label="Chiudi impostazioni" id="closePreferences">×</button><span class="eyebrow">IL TUO SPAZIO</span><h2>Come ti piace giocare.</h2><div class="settings-grid">${select('language','Lingua',[['it','Italiano'],['en','English'],['es','Español'],['fr','Français'],['de','Deutsch']],s)}${select('theme','Aspetto',[['system','Automatico · sistema'],['light','Chiaro'],['dark','Scuro']],s)}${select('board','Scacchiera',[['green','Verde classico'],['walnut','Noce'],['slate','Ardesia']],s)}${select('animation','Movimento dei pezzi',[['normal','Fluido'],['slow','Lento'],['off','Disattivato']],s)}${select('coachTone','Tono del coach',[['warm','Incoraggiante'],['direct','Diretto'],['quiet','Essenziale']],s)}${select('coachFrequency','Quando commentare',[['all','Ogni mia mossa'],['errors','Solo mosse da rivedere']],s)}</div><p class="muted">Traduzioni di interfaccia e coach. Alcune note del catalogo e informazioni tecniche sono ancora in italiano.</p><div class="settings-checks">${[['coachHints','Consenti indizi strategici su richiesta'],['coordinates','Coordinate sulla scacchiera'],['legal','Mostra mosse legali'],['sound','Suono delle mosse']].map(([key,label])=>`<label><input data-setting="${key}" type="checkbox" ${s[key]?'checked':''}>${label}</label>`).join('')}</div><hr><div class="avatar-custom"><div id="avatarPreview">${avatarSVG(s)}</div><div><span class="eyebrow">IL TUO ISTRUTTORE</span><h3>Crea il tuo coach</h3><p>Un compagno illustrato, con lo stile che scegli tu.</p></div></div><label class="name-field">Nome del coach<input data-setting="coachName" maxlength="18" value="${esc(s.coachName)}"></label><div class="settings-grid">${select('avatarShape','Forma',[['round','Morbida'],['square','Robot'],['cat','Gatto']],s)}${select('avatarColor','Colore',[['sage','Salvia'],['sky','Cielo'],['plum','Lilla'],['sun','Miele']],s)}${select('avatarEyes','Espressione',[['friendly','Curioso'],['focused','Concentrato'],['happy','Sorridente']],s)}${select('avatarAccessory','Accessorio',[['none','Nessuno'],['glasses','Occhiali'],['crown','Corona'],['headphones','Cuffie']],s)}</div><p id="settingsStatus" role="status" class="muted">Preferenze salvate su questo dispositivo.</p><button id="resetSettings" class="text-button">Ripristina le impostazioni</button>`;
addUpdates(dialog);
dialog.querySelector('#closePreferences').onclick=()=>dialog.close();dialog.onchange=e=>{const key=e.target.dataset.setting;if(!key)return;const saved=saveSettings({[key]:e.target.type==='checkbox'?e.target.checked:e.target.value,...(key.startsWith('avatar')||key.startsWith('coach')?{coachPreset:'custom'}:{})});dialog.querySelector('#avatarPreview').innerHTML=avatarSVG();dialog.querySelector('#settingsStatus').textContent=saved?'Preferenze salvate su questo dispositivo.':'Memoria non disponibile: impostazioni attive solo in questa sessione.'};dialog.querySelector('#resetSettings').onclick=async()=>{const {defaults}=await import('./settings.js');saveSettings(defaults);renderSettings()}}
export function openSettings(){renderSettings();dialog.showModal()}
const header=document.querySelector('header');const nav=document.createElement('nav');nav.className='app-nav';nav.setAttribute('aria-label','Menu principale');const page=navigationPage(location.pathname);nav.innerHTML=[['coach.html','Gioca'],['index.html','Analizza'],['progress.html','Progressi'],['practice.html','Esercizi'],['openings.html','Aperture']].map(([url,label])=>`<a href="${url}" ${page===url?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${({Gioca:"♟",Analizza:"◈",Progressi:"↗",Esercizi:"◎",Aperture:"▤"})[label]}</span><span>${label}</span></a>`).join('')+`<button id="preferencesButton" aria-label="Impostazioni e avatar"><span class="nav-icon" aria-hidden="true">⚙</span><span>Impostazioni</span></button>`;header.append(nav);document.querySelector('#preferencesButton').onclick=openSettings;document.querySelectorAll('[data-open-settings]').forEach(b=>b.onclick=openSettings);

window.plystreakDesktop?.healthy().catch(()=>{});
